using UnityEngine;
using UnityEditor;

public class AssignRecipesToUI
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        CookingUI ui = GameObject.FindObjectOfType<CookingUI>(true);
        if (ui != null)
        {
            string[] guids = AssetDatabase.FindAssets("t:CookingRecipe");
            CookingRecipe[] allRecipes = new CookingRecipe[guids.Length];
            for (int i = 0; i < guids.Length; i++)
            {
                string path = AssetDatabase.GUIDToAssetPath(guids[i]);
                allRecipes[i] = AssetDatabase.LoadAssetAtPath<CookingRecipe>(path);
            }

            ui.recipes = allRecipes;
            EditorUtility.SetDirty(ui);

            // Attempt to save scene if in editor
            var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);

            sb.AppendLine("[SUCCESS] Added " + allRecipes.Length + " recipes to CookingUI in scene: " + scene.name);
        }
        else
        {
            sb.AppendLine("[ERROR] CookingUI not found in scene!");
        }

        return sb.ToString();
    }
}
